import z3

v = 10
b = 60
r = 18
k = 3
lam = 4

# Create variables as Ints (0 or 1)
x = [[z3.Int(f'x_{i}_{j}') for j in range(b)] for i in range(v)]

solver = z3.Solver()

# Each variable is 0 or 1
for i in range(v):
    for j in range(b):
        solver.add(z3.Or(x[i][j] == 0, x[i][j] == 1))

# Row sums = r
for i in range(v):
    solver.add(z3.Sum([x[i][j] for j in range(b)]) == r)

# Column sums = k
for j in range(b):
    solver.add(z3.Sum([x[i][j] for i in range(v)]) == k)

# Pairwise inner products = lam
for i1 in range(v):
    for i2 in range(i1+1, v):
        solver.add(z3.Sum([x[i1][j] * x[i2][j] for j in range(b)]) == lam)

# Check satisfiability
result = solver.check()
print(result)
if result == z3.sat:
    model = solver.model()
    # Extract solution
    sol = []
    for i in range(v):
        for j in range(b):
            sol.append(model.eval(x[i][j]).as_long())
    print("Solution found")
    # Verify
    for i in range(v):
        row_sum = sum(sol[i*b + j] for j in range(b))
        print(f"Row {i} sum: {row_sum}")
    for j in range(b):
        col_sum = sum(sol[i*b + j] for i in range(v))
        if col_sum != k:
            print(f"Column {j} sum: {col_sum}")
    for i1 in range(v):
        for i2 in range(i1+1, v):
            inner = sum(sol[i1*b + j] * sol[i2*b + j] for j in range(b))
            if inner != lam:
                print(f"Pair ({i1},{i2}) inner: {inner}")
    print("Verification done")
else:
    print("UNSAT")
